Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.

(* [comment removed for export] *)
Ltac hstore1 WR A :=
  lazymatch type of WR with wr_at asegs ?mm ?B ?n =>
    let WRC := fresh "WRC" in let junk := fresh "junk" in let CELL := fresh "CELL" in let SOK := fresh "SOK" in
    assert (WRC : wr_at asegs mm A 1) by (apply (wr_at_sub mm B n); [exact WR| lia| lia| lia]);
    destruct (wr_at_rw_CB mm A 1 WRC ltac:(lia)) as (junk & CELL); change (Z.to_nat 1) with 1%nat in CELL;
    pose proof (rw_cells_store_ok_at asegs mm A [CB 1 junk] 0 (CB 1 junk) 1 (Z_to_bv 64 A) CELL eq_refl eq_refl ltac:(unfold wa; f_equal; lia)) as SOK;
    zstep; clear CELL WRC junk; try store_done
  end.
(* [comment removed for export] *)
Ltac hload1 WR A :=
  lazymatch type of WR with wr_at asegs ?mm ?B ?n =>
    let WRC := fresh "WRC" in let junk := fresh "junk" in let CELL := fresh "CELL" in let RD := fresh "RD" in let wv := fresh "bvl" in
    assert (WRC : wr_at asegs mm A 1) by (apply (wr_at_sub mm B n); [exact WR| lia| lia| lia]);
    destruct (wr_at_rw_CB mm A 1 WRC ltac:(lia)) as (junk & CELL); change (Z.to_nat 1) with 1%nat in CELL;
    pose proof (rw_cells_read_at asegs mm A [CB 1 junk] 0 (CB 1 junk) 1 (Z_to_bv 64 A) CELL eq_refl eq_refl ltac:(unfold wa; f_equal; lia)) as RD;
    lstep; clear RD
  end.

(* [comment removed for export] *)
Definition flr_tab_exit (sp gp tp s0 s1 s2 s4 s6 s7 s8 s9 s10 s11 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (T : Z) : machine_state -> Prop :=
  fun ms' => exists (ra' t0' t1' t2' a3' a4' a5' a6' a7' t3' t4' t5' : word) (m' : mem),
    ms' = MS (mkR ra' sp gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 (T + 256)) (Z_to_bv 64 256) (Z_to_bv 64 1) a3' a4' a5' a6' a7'
                  s2 (Z_to_bv 64 0) s4 (Z_to_bv 64 T) s6 s7 s8 s9 s10 s11 t3' t4' t5' t6)
