  wr_at asegs m T 256 -> acc asegs m T 256 -> mem_inv asegs m ->
  evt asegs (flr_tab_exit sp gp tp s0 s1 (Z_to_bv 64 2147450880) s4 s6 s7 s8 s9 s10 s11 t6 F fc m T)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 A0) (Z_to_bv 64 AI) (Z_to_bv 64 1) a3 a4 a5 a6 a7
             (Z_to_bv 64 2147450880) (Z_to_bv 64 S3) s4 (Z_to_bv 64 T) s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 flr_th) fc None m (seg_rom asegs)).
