(* [comment removed for export] *)
Definition flr_bytes_exit (ra sp gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (D nD X2 N : Z)
    : machine_state -> Prop :=
  fun ms' => exists (a0' a5' a6' a7' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0' (Z_to_bv 64 N) (Z_to_bv 64 X2) (Z_to_bv 64 0) (Z_to_bv 64 X2) a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 flr_ll) fc None m' (seg_rom asegs)
    /\ munch [(D, D + nD)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma flr_bytes : forall (n : nat) (j : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 s4 s9 t3 t4 t5 t6 a0 a5 a6 a7 : word) F fc (m : mem) (D nD B T L N bpl A1 A2 A3 A4 : Z),
  Z.of_nat n = N - j -> 0 <= j < N -> A1 = j -> A2 = L + j -> A3 = N - j -> A4 = L + j ->
  1 <= N <= bpl -> bpl mod 4 = 0 -> bpl <= 2504 ->
  0 < D -> D + nD <= 2^47 -> (D + nD <= 0x7fff7000 \/ 0x10007fff8000 <= D) -> L mod 4 = 0 -> D <= L -> L + bpl <= D + nD ->
  0 < B -> B mod 4 = 0 -> B + bpl <= 2^47 -> (B + bpl <= 0x7fff7000 \/ 0x10007fff8000 <= B) ->
  0 < T -> T + 256 <= 2^47 -> (T + 256 <= 0x7fff7000 \/ 0x10007fff8000 <= T) ->
  4 <= B -> 4 <= L ->
  wr_at asegs m D nD -> acc asegs m D nD -> wr_at asegs m B bpl -> acc asegs m B bpl -> wr_at asegs m T 256 -> acc asegs m T 256 -> mem_inv asegs m ->
  evt asegs (flr_bytes_exit ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 2147450880) (Z_to_bv 64 (bpl - 1)) s4 (Z_to_bv 64 T) (Z_to_bv 64 3) (Z_to_bv 64 1) (Z_to_bv 64 B)
               s9 (Z_to_bv 64 L) (Z_to_bv 64 1) t3 t4 t5 t6 F fc m D nD (L + N) N)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 (Z_to_bv 64 A1) (Z_to_bv 64 A2) (Z_to_bv 64 A3) (Z_to_bv 64 A4) a5 a6 a7
             (Z_to_bv 64 2147450880) (Z_to_bv 64 (bpl - 1)) s4 (Z_to_bv 64 T) (Z_to_bv 64 3) (Z_to_bv 64 1) (Z_to_bv 64 B) s9 (Z_to_bv 64 L) (Z_to_bv 64 1) t3 t4 t5 t6)
